const RATE = 2;

type Bucket = { tokens: number; last: number };

function allow(b: Bucket, now: number): boolean {
	const elapsed = now - b.last;
	b.tokens = b.tokens + elapsed * RATE;
	b.last = now;
	if (b.tokens >= 1) {
		b.tokens -= 1;
		return true;
	}
	return false;
}

